package com.ruoyi.kangaroo.ext.operations;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.ruoyi.kangaroo.ext.KgJdbc.p;
import static com.ruoyi.kangaroo.ext.operations.OpsRules.*;
import java.util.*;
import com.alibaba.fastjson2.JSON;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.kangaroo.security.admin.AdminCityContext;

class OperationsViewerDatabaseTest extends OperationsReminderDatabaseTest {
    OpsViewerGrants viewers;OpsTeamReports reports;
    @BeforeEach void setupViewer(){db.update("delete from kg_ops_viewer_change",p());db.update("delete from kg_ops_viewer",p());db.update("delete from kg_ops_monthly",p());viewers=new OpsViewerGrants();wire(viewers,"db",db);reports=new OpsTeamReports();OpsMonthly monthly=new OpsMonthly();wire(monthly,"db",db,"scope",scope);wire(reports,"db",db,"grants",viewers,"daily",daily,"monthly",monthly,"export",new OpsExport(),"weekly",weekly);}
    Map<String,Object> grant(long uid){return tx.execute(s->viewers.save(uid,p("enabled",true,"revision",0L,"reason","负责人查阅已提交报表"),1,"测试管理员"));}
    Map<String,Object> manual(){return p("tomorrowPlan","明日回访","facilities","无","shortages","无","yesterdayIssues","无","activityPlan","无","activityNote","","offlineIncome","0","expenses",Collections.emptyList(),"remedies",p());}
    Map<String,Object> report(long uid,long city,boolean submit){Map<String,Object> r=tx.execute(s->daily.open(uid,city,"keeper","2026-11-15"));return submit?tx.execute(s->daily.save(uid,number(r.get("reportId")),p("revision",r.get("revision"),"manual",manual()),true)):r;}
    @Test void unauthorizedAccountAndStaffCannotReadAllReports(){Map<String,Object> r=report(KEEPER,CITY,true);assertFalse(viewers.allowed(MANAGER));assertThrows(ServiceException.class,()->reports.list(MANAGER,"daily","2026-11",null,"",1));assertThrows(ServiceException.class,()->reports.detail(MANAGER,"daily",number(r.get("reportId"))));assertEquals(false,reports.access(MANAGER).get("allowed"));}
    @Test void explicitGrantReadsMultipleCitiesWithoutCreatingStaffPermissions(){report(KEEPER,CITY,true);report(STRANGER,OTHER,true);long before=count("kg_staff_grant");grant(SECOND);assertEquals(2L,number(reports.list(SECOND,"daily","2026-11",null,"",1).get("total")));assertEquals(1L,number(reports.list(SECOND,"daily","2026-11",OTHER,"",1).get("total")));assertEquals(before,count("kg_staff_grant"));assertTrue(scope.owned(SECOND).isEmpty());assertThrows(ServiceException.class,()->daily.open(SECOND,CITY,"keeper","2026-11-15"));}
    @Test void dailyDraftCannotBeListedOrGuessedById(){Map<String,Object> r=report(KEEPER,CITY,false);grant(SECOND);assertEquals(0L,number(reports.list(SECOND,"daily","2026-11",null,"",1).get("total")));assertThrows(ServiceException.class,()->reports.detail(SECOND,"daily",number(r.get("reportId"))));}
    @Test void revokeTakesEffectImmediatelyAndAuditsBothActions(){Map<String,Object> r=report(KEEPER,CITY,true);grant(SECOND);assertTrue(JSON.toJSONString(reports.detail(SECOND,"daily",number(r.get("reportId")))).contains("明日回访"));tx.execute(s->viewers.save(SECOND,p("enabled",false,"revision",1L,"reason","岗位调整撤销查阅"),1,"测试管理员"));assertFalse(viewers.allowed(SECOND));assertThrows(ServiceException.class,()->reports.detail(SECOND,"daily",number(r.get("reportId"))));assertEquals(2,viewers.history(SECOND).size());}
    @Test void limitedCityAdminCannotGrantOrSearchGlobalAccounts(){AdminCityContext.set(Arrays.asList(CITY));assertThrows(ServiceException.class,()->grant(SECOND));assertThrows(ServiceException.class,()->viewers.search("测试"));assertThrows(ServiceException.class,()->viewers.list());AdminCityContext.clear();assertFalse(viewers.allowed(SECOND));}
    @Test void staleGrantAndMissingReasonRejected(){grant(SECOND);assertThrows(ServiceException.class,()->tx.execute(s->viewers.save(SECOND,p("enabled",false,"revision",0L,"reason","过期请求"),1,"管理员")));assertThrows(ServiceException.class,()->tx.execute(s->viewers.save(SECOND,p("enabled",false,"revision",1L,"reason",""),1,"管理员")));assertEquals(1,viewers.history(SECOND).size());}
    @Test void weeklyReadsFrozenSubmittedContentAndExcludesReturnedDrafts(){grant(SECOND);Map<String,Object> snap=p("bizCols",Arrays.asList(p("label","总营收(元)","value","123.45")));long id=db.insert("kg_weekly_report",p("store_id",STORE,"week_start","2026-11-09","status","submitted","report_type","ops","submitted_by",KEEPER,"submitted_name","测试主理人","submitted_time","2026-11-15 18:00:00","snapshot",JSON.toJSONString(snap),"note","本周完成接待","risk","无"));assertEquals(1L,number(reports.list(SECOND,"weekly","2026-11",CITY,"测试",1).get("total")));String detail=JSON.toJSONString(reports.detail(SECOND,"weekly",id));assertTrue(detail.contains("123.45"));assertTrue(detail.contains("本周完成接待"));db.updateRow("kg_weekly_report","report_id",id,p("status","returned"));assertEquals(0L,number(reports.list(SECOND,"weekly","2026-11",null,"",1).get("total")));assertThrows(ServiceException.class,()->reports.detail(SECOND,"weekly",id));}
    @Test void disabledAccountCannotUseActiveGrantButGrantCanBeRevoked(){grant(SECOND);try{db.updateRow("kg_app_user","user_id",SECOND,p("status","1"));assertFalse(viewers.allowed(SECOND));assertThrows(ServiceException.class,()->reports.list(SECOND,"daily","2026-11",null,"",1));tx.execute(s->viewers.save(SECOND,p("enabled",false,"revision",1L,"reason","账号停用"),1,"管理员"));}finally{db.updateRow("kg_app_user","user_id",SECOND,p("status","0"));}assertFalse(viewers.allowed(SECOND));}
    @Test void filtersPaginationAndValidationNeverReturnUnsubmittedRecords(){grant(SECOND);Map<String,Object> r=report(KEEPER,CITY,true);assertEquals(0L,number(reports.list(SECOND,"daily","2026-10",null,"",1).get("total")));assertEquals(0L,number(reports.list(SECOND,"daily","2026-11",null,"不存在的人",1).get("total")));assertEquals(0,((List)reports.list(SECOND,"daily","2026-11",null,"",2).get("rows")).size());assertThrows(ServiceException.class,()->reports.list(SECOND,"../../users","2026-11",null,"",1));assertThrows(ServiceException.class,()->reports.list(SECOND,"daily","bad",null,"",1));assertThrows(ServiceException.class,()->reports.detail(SECOND,"other",number(r.get("reportId"))));}
    @Test void monthlySummaryIsReadOnlyAndVisibleAcrossCities(){grant(SECOND);Map<String,Object> snapshot=p("counts",p(),"progress",Collections.emptyList(),"actions",Collections.emptyList(),"strengths",Arrays.asList("本月完成接待"),"gaps",Collections.emptyList(),"suggestions",Collections.emptyList(),"submittedReports",1,"draftReports",0);long id=db.insert("kg_ops_monthly",p("month_key","2026-10","city_id",OTHER,"role_code","keeper","owner_id",STRANGER,"owner_name","异地负责人","city_name","催报测试市"+OTHER,"store_ids","[197004]","summary_json",JSON.toJSONString(snapshot),"generated_at","2026-11-01 00:30:00"));assertEquals(1L,number(reports.list(SECOND,"monthly","2026-10",OTHER,"异地",1).get("total")));assertTrue(JSON.toJSONString(reports.detail(SECOND,"monthly",id)).contains("本月完成接待"));assertEquals(1L,count("kg_ops_monthly"));}
}
